                        delta = d[r[k - 1]][c] + d[c][r[k]] - d[r[k - 1]][r[k]]
                    if best_delta is None or delta < best_delta or (delta == best_delta and (i, k, c) < (best_idx, best_pos, c)):
                        best_idx = i
                        best_pos = k
                        best_delta = delta
            if best_idx is None:
                routes.append([c])
            else:
                routes[best_idx].insert(best_pos, c)

    # Remove accidental duplicates by keeping first occurrence and repairing omissions
    seen = set()
    cleaned = []
    for r in routes:
        nr = []
        for c in r:
            if c not in seen:
                seen.add(c)
                nr.append(c)
        if nr:
            cleaned.append(nr)
    routes = cleaned
    present = set()
    for r in routes:
        for c in r:
            present.add(c)
    missing = [c for c in customers if c not in present]
    for c in missing:
        routes.append([c])

    return routes
